import itertools

def get_degree(n, edges, v):
    degree = 0
    for u1, v1 in edges:
        if u1 == v or v1 == v:
            degree += 1
    return degree

def get_clique_number(n, edges):
    # Simple clique finder for small graphs
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    max_clique = 0
    for i in range(1, n + 1):
        for clique in itertools.combinations(range(n), i):
            is_clique = True
            for u, v in itertools.combinations(clique, 2):
                if v not in adj[u]:
                    is_clique = False
                    break
            if is_clique:
                max_clique = max(max_clique, i)
    return max_clique

def get_chromatic_number(n, edges):
    # Simple coloring
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for num_colors in range(1, n + 1):
        # Try to color with num_colors
        coloring = [-1] * n
        def can_color(v):
            if v == n:
                return True
            for c in range(num_colors):
                safe = True
                for neighbor in adj[v]:
                    if coloring[neighbor] == c:
                        safe = False
                        break
                if safe:
                    coloring[v] = c
                    if can_color(v + 1):
                        return True
                    coloring[v] = -1
            return False
        if can_color(0):
            return num_colors
    return n

