    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Bron-Kerbosch or just check all subsets
    # For 15 vertices, checking all subsets is too much, but checking up to size 5 is fine
    for size in range(n, 0, -1):
        for clique in itertools.combinations(range(n), size):
            is_clique = True
            for u, v in itertools.combinations(clique, 2):
                if v not in adj[u]:
                    is_clique = False
                    break
            if is_clique:
                return size
    return 0

