            if v == n:
                return True
            for c in range(num_colors):
                safe = True
                for neighbor in adj[v]:
                    if coloring[neighbor] == c:
                        safe = False
                        break
                if safe:
                    coloring[v] = c
                    if can_color(v + 1):
